t)}.section-head{display:flex;align-items:end;justify-content:space-between;gap:1rem;margin-bottom:2rem}.section h2{margin:.25rem 0;font-size:clamp(2rem,4vw,3rem);letter-spacing:-.035em}.section-head p,.about p{color:var(--muted);line-height:1.75}.courses{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.course{display:flex;flex-direction:column;min-height:17rem;padding:1.35rem;border:1px solid #e0e6ea;border-radius:1rem;background:#fff;box-shadow:0 .5rem 1.6rem rgb(28 48 68 / 7%)}.course-icon{display:grid;place-items:center;width:2.8rem;height:2.8rem;border-radius:.8rem;color:var(--primary);background:color-mix(in srgb,var(--primary) 9%,#fff);font-size:1.25rem}.course h3{margin:1.1rem 0 .5rem;font-size:1.25rem}.course p{margin:0 0 1rem;color:var(--muted);line-height:1.55}.course-price{margin-top:auto;font-weight:850;font-size:1.2rem;color:var(--secondary)}.about{display:grid;grid-template-columns:.8fr 1.2fr;gap:4rem;align-items:start}.about-mark{padding:2rem;border-radius:1.2rem;color:#fff;background:linear-gradient(145deg,var(--primary),color-mix(in srgb,var(--primary) 70%,var(--secondary)))}.about-mark strong{display:block;font-size:3rem}.contact{display:flex;align-items:center;justify-content:space-between;gap:2rem;padding:2rem;border-radius:1.2rem;background:var(--secondary);color:#fff}.contact h2{margin:0}.contact p{margin:.5rem 0 0;color:#dfe8f2}.contact-links{display:flex;flex-wrap:wrap;gap:.7rem}.contact-links a{display:inline-flex;align-items:center;min-height:2.7rem;padding:.6rem .9rem;border:1px solid rgb(255 255 255 / 35%);border-radius:.65rem;color:#fff;text-decoration:none;font-weight:700}.footer{padding:2rem 0;color:var(--muted);border-top:1px solid #e4e9ec}.footer-row{display:flex;justify-content:space-between;gap:1rem}.preview{position:fixed;z-index:50;right:1rem;bottom:1rem;padding:.55rem .8rem;border-radius:999px;color:#704d00;background:#fff1bd;border:1px solid #e6ca65;font-size:.78rem;font-weight:800}@media(max-width:850px){.links a:not(.button){display:none}.courses{grid-template-columns:repeat(2,minmax(0,1fr))}.about{grid-template-columns:1fr;gap:1.5rem}.contact{align-items:flex-start;flex-direction:column}}@media(max-width:580px){.courses{grid-template-columns:1fr}.hero{padding:5rem 0 4rem}.section{padding:3.5rem 0}.section-head,.footer-row{align-items:flex-start;flex-direction:column}.brand span{display:none}}
