<header class="top"><nav class="shell nav"><a class="brand" href="#inicio"><?php if($logo!==''):?><img src="<?= $escape($assetBasePath.$logo) ?>" alt="<?= $escape($siteTitle) ?>"><?php else:?><span><?= $escape($siteTitle) ?></span><?php endif;?></a><div class="links"><a href="#cursos">Cursos</a><a href="#sobre">Sobre</a><a href="#contato">Contato</a><a class="button" href="#cursos"><?= ($site['selected_mode']??'catalog')==='store'?'Comprar curso':'Ver catálogo' ?></a></div></nav></header>
<main><section class="hero" id="inicio"><div class="shell hero-content"><p class="eyebrow"><?= $escape($siteTitle) ?></p><h1><?= $escape((string)$site['hero_title']) ?></h1><p><?= $escape((string)$site['hero_text']) ?></p><a class="button" href="#cursos"><?= ($site['selected_mode']??'catalog')==='store'?'Escolher meu curso':'Conhecer os cursos' ?></a></div></section>
