<section class="section" id="sobre"><div class="shell about"><aside class="about-mark"><small>Conhecimento que transforma</small><strong><?= $escape($siteTitle) ?></strong></aside><div><p class="eyebrow">Institucional</p><h2><?= $escape((string)($site['about_title']?:'Sobre nós')) ?></h2><p><?= nl2br($escape((string)$site['about_text'])) ?></p></div></div></section>
<section class="section" id="contato"><div class="shell contact"><div><h2>Vamos conversar?</h2><p>Fale com nossa equipe e encontre o curso ideal.</p></div><div class="contact-links"><?php if($whatsappInternational!==''):?><a href="https://wa.me/<?= $escape($whatsappInternational) ?>" target="_blank">WhatsApp</a><?php endif;?><?php if(!empty($site['contact_email'])):?><a href="mailto:<?= $escape($site['contact_email']) ?>">E-mail</a><?php endif;?><?php if(!empty($site['instagram_url'])):?><a href="<?= $escape($site['instagram_url']) ?>" target="_blank">Instagram</a><?php endif;?><?php if(!empty($site['facebook_url'])):?><a href="<?= $escape($site['facebook_url']) ?>" target="_blank">Facebook</a><?php endif;?></div></div></section></main>
<footer class="footer"><div class="shell footer-row"><strong><?= $escape($siteTitle) ?></strong><span>© <?= date('Y') ?> · Todos os direitos reservados.</span></div></footer><?php if(!empty($preview)):?><span class="preview">Modo de pré-visualização</span><?php endif;?></body></html>
